import{_ as n,o as h,c as i,a2 as o}from"./chunks/framework.mRCPFc5l.js";const s=JSON.parse('{"title":"Milestone gắn vào Portrait thế nào","description":"","frontmatter":{},"headers":[],"relativePath":"portrait/milestone.md","filePath":"portrait/milestone.md"}'),e={name:"portrait/milestone.md"};function a(c,t,g,r,l,m){return h(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="milestone-gan-vao-portrait-the-nao" tabindex="-1">Milestone gắn vào Portrait thế nào <a class="header-anchor" href="#milestone-gan-vao-portrait-the-nao" aria-label="Permalink to &quot;Milestone gắn vào Portrait thế nào&quot;">​</a></h1><p>Trên trang này# Milestone gắn vào Portrait thế nào <a href="#milestone-gan-vao-portrait-the-nao">​</a> Portrait là hướng đi. Milestone là những cột mốc dọc đường — cụ thể, có ngày, kiểm tra được. Không có milestone, Portrait chỉ là một danh sách mong ước. Không có Portrait, milestone chỉ là một danh sách việc phải làm.</p><h2 id="mot-milestone-trong-nhu-the-nao-​" tabindex="-1">Một milestone trông như thế nào <a href="#mot-milestone-trong-nhu-the-nao">​</a> <a class="header-anchor" href="#mot-milestone-trong-nhu-the-nao-​" aria-label="Permalink to &quot;Một milestone trông như thế nào [​](#mot-milestone-trong-nhu-the-nao)&quot;">​</a></h2><p>textMilestone ├── loại — kỳ thi · học thuật · năng lực · ngôn ngữ · thói quen │ · hồ sơ · trải nghiệm · phát triển cá nhân ├── tên — &quot;IELTS lần 1&quot; ├── mục tiêu — 6.5 ├── ngày — 01/2027 ├── kỳ vọng — mức dự kiến đạt được vào lúc đó ├── kết quả thật— điền sau khi xong └── trạng thái — dự kiến · đang làm · đạt · trượt · dời lạiHai trường đáng chú ý là <strong>kỳ vọng</strong> và <strong>kết quả thật</strong>. Ghi cả hai cho phép nhìn lại: mình đã dự đoán đúng tới đâu? Một gia đình liên tục đặt kỳ vọng cao hơn thực tế 1.5 điểm cần biết điều đó — không phải để tự trách, mà để lần sau đặt mốc sát hơn.</p><h2 id="chuoi-milestone-quan-trong-hon-tung-milestone-​" tabindex="-1">Chuỗi milestone quan trọng hơn từng milestone <a href="#chuoi-milestone-quan-trong-hon-tung-milestone">​</a> <a class="header-anchor" href="#chuoi-milestone-quan-trong-hon-tung-milestone-​" aria-label="Permalink to &quot;Chuỗi milestone quan trọng hơn từng milestone [​](#chuoi-milestone-quan-trong-hon-tung-milestone)&quot;">​</a></h2><p>Một mục tiêu xa mà không có mốc trung gian thì hoặc bị bỏ quên, hoặc gây hoảng loạn vào phút chót. Chia ra: text09/2026 Thi thử để biết đang ở đâu → 5.5 01/2027 Thi thật lần 1, mục tiêu 6.5 06/2027 Thi lần 2, mục tiêu 7.0 12/2027 Thi lần 3, mục tiêu 7.5+Chuỗi này làm được ba việc: cho một điểm xuất phát có thật thay vì phỏng đoán; biến một mục tiêu xa thành bốn quyết định gần; và cho phép <strong>sửa hướng sớm</strong> — nếu tháng 1/2027 chỉ được 6.0, còn đủ thời gian đổi cách làm, thay vì phát hiện ra vào tháng 11/2027.</p><h2 id="milestone-khong-chi-danh-cho-ky-thi-​" tabindex="-1">Milestone không chỉ dành cho kỳ thi <a href="#milestone-khong-chi-danh-cho-ky-thi">​</a> <a class="header-anchor" href="#milestone-khong-chi-danh-cho-ky-thi-​" aria-label="Permalink to &quot;Milestone không chỉ dành cho kỳ thi [​](#milestone-khong-chi-danh-cho-ky-thi)&quot;">​</a></h2><p>Đây là chỗ dễ trượt nhất. Nếu mọi milestone đều là kỳ thi, Portrait sẽ lặng lẽ biến trở lại thành một bảng mục tiêu điểm số — và cả nhà quay về đúng chỗ cũ. Những milestone không phải kỳ thi, và đều kiểm tra được:</p><ul><li>&quot;Tự lên kế hoạch học cả tuần mà không cần bố mẹ nhắc&quot; — trước hè 2027.</li><li>&quot;Hoàn thành một dự án tự chọn từ đầu tới cuối, có sản phẩm cho người khác xem&quot; — trong năm nay.</li><li>&quot;Bơi được 400m liên tục.&quot;</li><li>&quot;Chủ động hỏi thầy cô khi không hiểu, ít nhất một lần mỗi tuần&quot; — trong hai tháng.</li><li>&quot;Đọc hết một cuốn sách tiếng Anh.&quot; Cái thứ tư đáng chú ý: với một đứa trẻ ngại hỏi, milestone đó có giá trị hơn nhiều so với việc tăng nửa điểm trung bình.</li></ul><h2 id="milestone-chi-thanh-muc-tieu-that-khi-gia-đinh-chot-​" tabindex="-1">Milestone chỉ thành mục tiêu thật khi gia đình chốt <a href="#milestone-chi-thanh-muc-tieu-that-khi-gia-đinh-chot">​</a> <a class="header-anchor" href="#milestone-chi-thanh-muc-tieu-that-khi-gia-đinh-chot-​" aria-label="Permalink to &quot;Milestone chỉ thành mục tiêu thật khi gia đình chốt [​](#milestone-chi-thanh-muc-tieu-that-khi-gia-đinh-chot)&quot;">​</a></h2><p>Viết một milestone vào Portrait <strong>không</strong> tự động khiến hệ thống dồn tài nguyên vào nó. Nó vẫn là nguyện vọng. Khi gia đình chốt — có xác nhận rõ ràng — milestone loại kỳ thi mới trở thành mục tiêu thật của hệ thống: có ngày, có mức cần đạt, và từ đó Nemo12 bắt đầu tính <a href="/decisions/readiness-vs-mastery">mức sẵn sàng</a> so với mốc đó và điều chỉnh gợi ý hằng ngày. Bước xác nhận này cố ý có ma sát. Chuyển một mong muốn thành một mục tiêu vận hành là quyết định lớn — nó sẽ đổi việc con làm mỗi ngày trong nhiều tháng. Nó không nên xảy ra chỉ vì ai đó gõ một dòng vào ô nhập.</p><h2 id="khi-milestone-khong-thuc-te-​" tabindex="-1">Khi milestone không thực tế <a href="#khi-milestone-khong-thuc-te">​</a> <a class="header-anchor" href="#khi-milestone-khong-thuc-te-​" aria-label="Permalink to &quot;Khi milestone không thực tế [​](#khi-milestone-khong-thuc-te)&quot;">​</a></h2><p>Nemo12 phát hiện được điều này, và cách nó xử lý phản ánh nguyên tắc của cả hệ thống. Ví dụ: mục tiêu IELTS 8.0 trước 06/2027, trong khi hiện tại 5.0, còn sắp thi học kỳ, và learner đang có dấu hiệu căng thẳng cao. Hệ thống <strong>không</strong> xoá mục tiêu và <strong>không</strong> nói &quot;không khả thi, bỏ đi&quot;. Nó giữ nguyên nguyện vọng 8.0, và đề xuất sửa các mốc trung gian: có lẽ 6.5 vào 06/2027 và 8.0 vào 2028. Kèm theo là lý do và cái giá của phương án giữ nguyên mốc cũ. Quyết định cuối vẫn thuộc về gia đình. Việc của hệ thống là không để một gia đình đi mười tháng trong ảo tưởng rồi mới biết.</p><h2 id="truot-mot-milestone-khong-phai-that-bai-​" tabindex="-1">Trượt một milestone không phải thất bại <a href="#truot-mot-milestone-khong-phai-that-bai">​</a> <a class="header-anchor" href="#truot-mot-milestone-khong-phai-that-bai-​" aria-label="Permalink to &quot;Trượt một milestone không phải thất bại [​](#truot-mot-milestone-khong-phai-that-bai)&quot;">​</a></h2><p>Trạng thái &quot;trượt&quot; và &quot;dời lại&quot; đều là trạng thái hợp lệ, được lưu lại bình thường, không có gì tiêu cực gắn kèm. Một milestone trượt cho thông tin: hoặc mốc đặt quá cao, hoặc cách làm chưa hiệu quả, hoặc có chuyện xảy ra. Cả ba đều hữu ích, và cả ba đều dẫn tới hành động cụ thể. Một gia đình không bao giờ trượt milestone nào nhiều khả năng đang đặt mốc quá dễ. Portrait cho biết đi đâu. Milestone cho biết đang ở đâu trên đường. Thiếu cái nào thì cái còn lại cũng mất tác dụng. <a href="/portrait/vi-du">Ví dụ: ba chân dung khác nhau →</a></p>',15)])])}const k=n(e,[["render",a]]);export{s as __pageData,k as default};
